method Strongest_Extension(class_name: string, extensions: seq<string>) returns (result: string)
    requires class_name != ""
    requires extensions != null
    ensures result == class_name + "." + strongest_extension
    ensures strongest_extension in extensions
    ensures forall e1, e2 :: e1 in extensions && e2 in extensions && (Strength(e1) == Strength(e2) ==> e1 == e2 || e1 < e2)
{
    var strongest_extension := ""; 
    var max_strength := -inf;

    for ext in extensions {
        var strength := Strength(ext);
        if strength > max_strength {
            max_strength := strength;
            strongest_extension := ext;
        }
    }

    result := class_name + "." + strongest_extension;
}

function Strength(ext: string) : int
{
    var cap := CountUppercase(ext);
    var sm := CountLowercase(ext);
    cap - sm
}

function CountUppercase(s: string) : int
{
    var count := 0;
    var i := 0;
    while i < s.Length
        invariant 0 <= i <= s.Length
        invariant count == CountUppercase(s.Substring(0, i))
    {
        if IsUpper(s[i]) {
            count := count + 1;
        }
        i := i + 1;
    }
    count
}

function CountLowercase(s: string) : int
{
    var count := 0;
    var i := 0;
    while i < s.Length
        invariant 0 <= i <= s.Length
        invariant count == CountLowercase(s.Substring(0, i))
    {
        if IsLower(s[i]) {
            count := count + 1;
        }
        i := i + 1;
    }
    count
}

function IsUpper(c: char) : bool
{
    c >= 'A' && c <= 'Z'
}

function IsLower(c: char) : bool
{
    c >= 'a' && c <= 'z'
}
